package br.com.admeclesial.application.financeiro;
import org.springframework.beans.factory.annotation.Autowired;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService;
import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*;
@Service public class PagamentoApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final PagamentoRepository repo; final ContaFinanceiraRepository contas; final ParcelaAPagarRepository parcelas; final AlocacaoPagamentoRepository alocacoes; final PagamentoMovimentacaoRepository links; final MovimentacaoFinanceiraRepository movimentos; final ContaAPagarRepository contasPagar; public PagamentoApplicationService(PagamentoRepository r,ContaFinanceiraRepository c,ParcelaAPagarRepository p,AlocacaoPagamentoRepository a,PagamentoMovimentacaoRepository l,MovimentacaoFinanceiraRepository m,ContaAPagarRepository cp){repo=r;contas=c;parcelas=p;alocacoes=a;links=l;movimentos=m;contasPagar=cp;} @Transactional public Pagamento criar(PagamentoRequest r){var conta=contas.findByUuid(r.contaFinanceiraUuid()).orElseThrow(()->new IllegalArgumentException("Conta financeira não encontrada."));if(seguranca!=null)seguranca.validarAcessoId(conta.getOrganizacaoEclesialId());if(!conta.getAtivo())throw new IllegalArgumentException("Conta financeira inativa.");if(r.alocacoes().isEmpty())throw new IllegalArgumentException("Informe ao menos uma parcela para o pagamento.");BigDecimal soma=BigDecimal.ZERO;Set<UUID> parcelasInformadas=new HashSet<>();List<ParcelaAPagar> ps=new ArrayList<>();for(var a:r.alocacoes()){if(!parcelasInformadas.add(a.parcelaAPagarUuid()))throw new IllegalArgumentException("A mesma parcela não pode aparecer mais de uma vez no pagamento.");var p=parcelas.findByUuid(a.parcelaAPagarUuid()).orElseThrow(()->new IllegalArgumentException("Parcela não encontrada."));var contaPagar=contasPagar.findById(p.getContaAPagarId()).orElseThrow();if(!conta.getOrganizacaoEclesialId().equals(contaPagar.getOrganizacaoEclesialId()))throw new IllegalArgumentException("A conta financeira e a conta a pagar devem pertencer à mesma organização.");if(contaPagar.getStatus()==StatusContaAPagar.CANCELADA)throw new IllegalArgumentException("A conta a pagar está cancelada.");if(p.getStatus()==StatusParcelaAPagar.CANCELADA||p.getStatus()==StatusParcelaAPagar.PAGA)throw new IllegalArgumentException("Parcela não está disponível para pagamento.");if(a.valor().compareTo(p.getValor())>0)throw new IllegalArgumentException("Valor alocado supera o valor da parcela.");var ja=alocacoes.sumValorPorParcela(p.getId());if(ja.add(a.valor()).compareTo(p.getValor())>0)throw new IllegalArgumentException("Valor alocado supera o saldo da parcela.");soma=soma.add(a.valor());ps.add(p);}if(soma.compareTo(r.valor())!=0)throw new IllegalArgumentException("A soma das alocações deve ser igual ao valor do pagamento.");var e=new Pagamento();e.setValor(r.valor());e.setDataPagamento(r.dataPagamento());e.setMeioPagamento(r.meioPagamento());e.setObservacao(r.observacao());e=repo.save(e);for(int i=0;i<r.alocacoes().size();i++){var ar=r.alocacoes().get(i);var p=ps.get(i);var a=new AlocacaoPagamento();a.setPagamentoId(e.getId());a.setParcelaAPagarId(p.getId());a.setValor(ar.valor());alocacoes.save(a);p.setStatus(alocacoes.sumValorPorParcela(p.getId()).compareTo(p.getValor())>=0?StatusParcelaAPagar.PAGA:StatusParcelaAPagar.ABERTA);parcelas.save(p);atualizarConta(p.getContaAPagarId());}var mov=new MovimentacaoFinanceira();mov.setContaFinanceiraId(conta.getId());mov.setTipo(TipoMovimentacaoFinanceira.SAIDA);mov.setValor(e.getValor());mov.setDataMovimentacao(e.getDataPagamento());mov.setDescricao("Pagamento " + e.getUuid());mov.setStatus(StatusMovimentacaoFinanceira.CONFIRMADA);mov=movimentos.save(mov);var pm=new PagamentoMovimentacao();pm.setPagamentoId(e.getId());pm.setMovimentacaoFinanceiraId(mov.getId());pm.setValor(e.getValor());links.save(pm);return e;} private void atualizarConta(Long contaId){var c=contasPagar.findById(contaId).orElseThrow();var ps=parcelas.findAllByContaAPagarIdOrderByNumeroAsc(contaId);boolean todas=ps.stream().allMatch(x->x.getStatus()==StatusParcelaAPagar.PAGA||x.getStatus()==StatusParcelaAPagar.CANCELADA);boolean alguma=ps.stream().anyMatch(x->x.getStatus()==StatusParcelaAPagar.PAGA);c.setStatus(todas&&alguma?StatusContaAPagar.PAGA:(alguma?StatusContaAPagar.PARCIALMENTE_PAGA:StatusContaAPagar.ABERTA));contasPagar.save(c);} @Transactional(readOnly=true) public List<Pagamento> listar(){return repo.findAllByOrderByDataPagamentoDesc().stream().filter(pag -> alocacoes.findAll().stream().filter(a->a.getPagamentoId().equals(pag.getId())).findFirst().map(a->parcelas.findById(a.getParcelaAPagarId()).flatMap(pa->contasPagar.findById(pa.getContaAPagarId())).map(cp->{try{if(seguranca!=null)seguranca.validarAcessoId(cp.getOrganizacaoEclesialId());return true;}catch(org.springframework.security.access.AccessDeniedException ex){return false;}}).orElse(false)).orElse(false)).toList();}}
